def solve(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Create result as copy of input
    result = [row[:] for row in grid]

    # Find all 0s connected to border using BFS/DFS
    from collections import deque

    # Mark all border-connected 0s as visited (don't change these)
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    # Add all 0s on the border to queue
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0 and not visited[r][c]:
                visited[r][c] = True
                queue.append((r, c))
    for c in range(cols):
        for r in [0, rows-1]:
            if grid[r][c] == 0 and not visited[r][c]:
                visited[r][c] = True
                queue.append((r, c))

    # BFS to find all 0s connected to border
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # Fill unvisited 0s with 1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                result[r][c] = 1

    return result
